package data;

import javax.enterprise.context.SessionScoped;
import javax.enterprise.inject.Default;
import javax.inject.Named;

import org.apache.deltaspike.data.api.EntityRepository;
import org.apache.deltaspike.data.api.Repository;

import model.Event;

/**
 * This is a basic DAO-like interface for use by JSF or EJB.
 * Original version was machine-generated by entity-gen.
 * Methods are implemented for us by Apache DeltaSpike Data.
 * The methods in the inherited interface suffice for many apps!
 * @author Ian Darwin
 */
@Named("eventList") @Default
@SessionScoped
@Repository
public interface EventList extends EntityRepository<Event, Long> {
	// can be empty initially
}
